  --kld-bg: #0d0d1a;
  --kld-panel-bg: rgba(18, 18, 28, 0.85);
  --kld-border: rgba(255, 0, 222, 0.6);
  --kld-border-glow: rgba(255, 0, 222, 0.8);
  --kld-accent: #ff00de;
  --kld-accent-cyan: #00eaff;
  --kld-text: #e0e0ff;
  --kld-text-dark: #8c8ca0;
  --kld-text-live: #ff4d4d;
  --kld-text-gold: #ffd700;
  --kld-font-main: 'Noto Sans SC', sans-serif;
  --kld-font-tech: 'Orbitron', sans-serif;
}
.status-data-container { display: none; }
StatusBlock {
  display: block;
  font-family: var(--kld-font-main);
  color: var(--kld-text);
  width: 100%;
  max-width: 600px;
  margin: 10px auto;
  font-size: 15px;
  background-color: var(--kld-bg);
  border: 1px solid var(--kld-border);
  border-radius: 8px;
  box-shadow: 0 0 20px var(--kld-border-glow), 0 0 5px var(--kld-border) inset;
  backdrop-filter: blur(10px);
  overflow: hidden;
  line-height: 1.6;
}
.kld-wrapper { padding: 10px; }
.kld-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 5px 10px;
  background: linear-gradient(to right, rgba(255,0,222,0.3), rgba(0,234,255,0.3));
  border-bottom: 1px solid var(--kld-accent);
}
.kld-header-title { font-family: var(--kld-font-tech); font-size: 1.2em; text-shadow: 0 0 5px var(--kld-accent); display:flex; align-items:center; }
.kld-header-title svg { width: 24px; height: 24px; margin-right: 8px; fill: var(--kld-accent); }
.kld-toggle-btn {
  background: var(--kld-accent);
  border: none;
  color: #fff;
  padding: 4px 10px;
  border-radius: 4px;
  cursor: pointer;
  font-weight: bold;
  font-family: var(--kld-font-main);
  box-shadow: 0 0 8px var(--kld-accent);
  transition: all 0.2s;
}
.kld-toggle-btn:hover { background: var(--kld-accent-cyan); box-shadow: 0 0 8px var(--kld-accent-cyan);}
.kld-content {
  display: block;
  padding: 10px 0 0 0;
}
.kld-global-info { display: flex; justify-content: space-around; font-size: 0.85em; color: var(--kld-text-dark); background: rgba(0,0,0,0.3); padding: 6px; border-radius: 4px; margin-bottom: 10px; }
.kld-global-info span { display: flex; align-items: center; }
.kld-global-info svg { width:14px; height:14px; margin-right:5px; fill: var(--kld-text-dark); }
.kld-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  padding-bottom: 10px;
  border-bottom: 1px dashed var(--kld-border);
}
.kld-tab {
  flex: 1 1 auto;
  cursor: pointer;
  padding: 6px 10px;
  border: 1px solid var(--kld-border);
  background: rgba(255, 0, 222, 0.1);
  border-radius: 4px;
  font-size: 0.95em;
  font-weight: 500;
  text-align: center;
  transition: all 0.2s ease;
  white-space: nowrap;
}
.kld-tab:hover { background: rgba(0, 234, 255, 0.3); border-color: var(--kld-accent-cyan); }
.kld-tab.active {
  background: var(--kld-accent);
  color: #fff;
  font-weight: 700;
  border-color: var(--kld-accent);
  box-shadow: 0 0 10px var(--kld-border-glow);
}
.kld-tab[data-char*="直播间"] { --live-accent: #ff4d4d; background: rgba(255, 77, 77, 0.1); border-color: var(--live-accent); }
.kld-tab[data-char*="直播间"].active { background: var(--live-accent); border-color: var(--live-accent); box-shadow: 0 0 10px var(--live-accent); }
.kld-details-panel { padding-top: 10px; }
.kld-live-view, .kld-char-view, .kld-user-view { display: none; }
.kld-live-header { display: flex; justify-content: space-between; align-items: center; padding: 5px; background: rgba(0,0,0,0.4); border-radius: 4px; margin-bottom: 8px; }
.kld-live-title-container { display:flex; align-items:center; }
.kld-live-status-dot { width: 10px; height: 10px; border-radius: 50%; background-color: var(--kld-text-dark); margin-right: 8px; }
.kld-live-status-dot.live { background-color: var(--kld-text-live); box-shadow: 0 0 8px var(--kld-text-live); animation: pulse 1.5s infinite; }
@keyframes pulse { 0% { opacity: 1; } 50% { opacity: 0.5; } 100% { opacity: 1; } }
.kld-live-title { font-weight: bold; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.kld-live-viewers { display: flex; align-items: center; font-family: var(--kld-font-tech); color: var(--kld-text-live); font-size: 1.1em; }
.kld-live-viewers svg { width:18px; height:18px; margin-right:5px; fill: var(--kld-text-live); }
.kld-danmaku-container, .kld-gift-container { max-height: 150px; overflow-y: auto; padding: 0 5px; margin-top: 10px; scrollbar-width: thin; scrollbar-color: #ff4d4d var(--kld-panel-bg); }
.kld-danmaku-container::-webkit-scrollbar, .kld-gift-container::-webkit-scrollbar { width: 5px; }
.kld-danmaku-container::-webkit-scrollbar-track, .kld-gift-container::-webkit-scrollbar-track { background: var(--kld-panel-bg); }
.kld-danmaku-container::-webkit-scrollbar-thumb, .kld-gift-container::-webkit-scrollbar-thumb { background-color: #ff4d4d; border-radius: 10px; }
.kld-danmaku-item { background: rgba(255,255,255,0.05); padding: 5px 10px; margin-bottom: 5px; border-radius: 3px; border-left: 3px solid #ff4d4d; font-size: 0.9em; }
.kld-gift-item { background: linear-gradient(90deg, rgba(255, 215, 0, 0.2), rgba(255, 215, 0, 0.05)); padding: 6px 12px; margin-bottom: 5px; border-radius: 3px; border-left: 3px solid var(--kld-text-gold); font-size: 0.9em; display:flex; align-items:center; justify-content:space-between; }
.kld-gift-item-content { color: var(--kld-text-gold); }
.kld-gift-item-user { color: var(--kld-text-dark); font-size:0.9em; }
.kld-section-title { font-family: var(--kld-font-tech); font-size: 1em; color:var(--kld-text-dark); margin-bottom: 5px; border-bottom: 1px solid var(--kld-text-dark); padding-bottom: 3px; }
.kld-content-grid { display: flex; flex-wrap: wrap; gap: 12px; }
.kld-left-panel { flex: 0 0 120px; text-align: center; }
.kld-avatar-frame { position: relative; width: 120px; height: 120px; margin-bottom: 8px; border-radius: 50%; overflow: hidden; border: 2px solid var(--kld-accent); box-shadow: 0 0 12px var(--kld-border-glow) inset, 0 0 12px var(--kld-border-glow); background: rgba(0,0,0,0.5);}
.kld-avatar, .user_avatar { width: 100%; height: 100%; object-fit: cover; object-position: center; transition: transform 0.3s; background-size: cover; background-position: center; }
.kld-avatar-frame:hover .kld-avatar, .kld-avatar-frame:hover .user_avatar { transform: scale(1.1); }
.kld-nickname { font-family: var(--kld-font-tech); color: var(--kld-accent); font-size: 1.1em; text-shadow: 0 0 5px var(--kld-accent); margin-top: 0; }
.kld-right-panel { flex-grow: 1; min-width: 0; }
.kld-gauge-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: 8px; margin-bottom: 10px; }
.kld-gauge-item .gauge-name { font-size: 0.9em; font-weight: 500; color: var(--kld-text-dark); margin-bottom: 2px; }
.kld-progress-bar { width: 100%; height: 20px; background: rgba(0,0,0,0.5); border-radius: 10px; position: relative; overflow: hidden; border: 1px solid rgba(0,0,0,0.5); }
.kld-progress-fill { height: 100%; background: linear-gradient(90deg, var(--kld-accent-cyan), var(--kld-accent)); transition: width 0.5s ease-out; }
.kld-progress-text { position: absolute; top:0; left:0; width:100%; height:100%; font-size: 0.8em; line-height: 20px; color: #fff; text-shadow: 1px 1px 2px #000; text-align: center; font-weight: bold; font-family:var(--kld-font-tech); }
.kld-info-grid { display: grid; grid-template-columns: 1fr; gap: 8px; }
.kld-info-block { background: rgba(0,0,0,0.3); padding: 8px 12px; border-radius: 4px; border-left: 3px solid var(--kld-accent-cyan); font-size: 0.95em; }
.kld-info-block p { margin: 0; }
.kld-info-block strong { color: var(--kld-text); font-weight: 600; margin-right: 5px; }
.kld-info-block span { color: var(--kld-text); }
.kld-info-cmd span { color: var(--kld-accent-cyan); font-weight: bold; }
.kld-bounty-block { background-image: linear-gradient(to right, rgba(0, 234, 255, 0.1), rgba(0,0,0,0)); padding: 6px 10px; border-radius: 4px; border-left: 3px solid var(--kld-accent-cyan); margin-bottom:6px; }
.kld-bounty-title { font-weight: bold; color: var(--kld-accent-cyan); }
.kld-bounty-reward { font-size: 0.85em; color: var(--kld-text-dark); }
.kld-parts-block { margin-top: 8px; }
.kld-parts-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: 6px; margin-top: 5px; }
.kld-part-item { text-align: left; background: rgba(0,0,0,0.5); padding: 4px 8px; border-radius: 4px; }
.kld-part-name { font-size: 0.85em; color: var(--kld-text-dark); display: inline-block; margin-right: 8px; }
.kld-part-status { font-size: 0.9em; font-weight: 500; color: var(--kld-text); }
</style>
</head>
<body>

<div class="status-data-container">$1</div>

<StatusBlock>
  <div class="kld-header">
    <div class="kld-header-title">
        <svg viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 18c-4.41 0-8-3.59-8-8s3.59-8 8-8 8 3.59 8 8-3.59 8-8 8zm-1-12h2v4h-2zm0 6h2v2h-2zm-3.25-5.04l1.41-1.41 2.47 2.47-1.41 1.41zm8.49 0l-1.41-1.41 1.41-1.41 1.41 1.41-1.41 1.41zM9.04 15.25l-2.47-2.47-1.41 1.41 2.47 2.47z"></path></svg>
        Kaleidoscope
    </div>
    <button class="kld-toggle-btn">折叠</button>
  </div>
  <div class="kld-wrapper">
    <div class="kld-content">
      <div class="kld-global-info"></div>
      <div class="kld-tabs"></div>
      <div class="kld-details-panel">
        <div class="kld-live-view"></div>
        <div class="kld-char-view"></div>
        <div class="kld-user-view"></div>
      </div>
    </div>
  </div>
</StatusBlock>

<script>
document.addEventListener('DOMContentLoaded', () => {
  const dataContainer = document.querySelector('.status-data-container'); if (!dataContainer) return;
  const avatarDatabase = { '天野诗织': 'https://img.remit.ee/api/file/BQACAgUAAyEGAASHRsPbAAIzN2h14akLyJ3pIe5u-T2KoI8JKEYaAALCFwAC5vuwV8l_rMUiXYZvNgQ.png', '白石莉音': 'https://img.remit.ee/api/file/BQACAgUAAyEGAASHRsPbAAIzOWh14aklsv4HxeZoQvuE6ykp9zTtAALEFwAC5vuwV2hnMGOuYZO6NgQ.png', '早乙女玲奈': 'https://img.remit.ee/api/file/BQACAgUAAyEGAASHRsPbAAIzO2h14apra4DkTrsH-YaOpQYE_hxcAALGFwAC5vuwV1elOdQZDjj5NgQ.png', '橘萌绘': 'https://img.remit.ee/api/file/BQACAgUAAyEGAASHRsPbAAIzOmh14ak5b07UnKo2u8KEP9PWPPciAALFFwAC5vuwV-2rBRbPw2jMNgQ.png', '如月莲': 'https://img.remit.ee/api/file/BQACAgUAAyEGAASHRsPbAAIzPWh15g-pwskJpAfIub0lfFw5agxpAALSFwAC5vuwV1YKtguDH1mUNgQ.png', '风间咲': 'https://img.remit.ee/api/file/BQACAgUAAyEGAASHRsPbAAIzPGh14a_H_vE7P6NYbMQIww-ZLGIsAALHFwAC5vuwV7WBgsg9LRleNgQ.png', };
  function parseData(text) { const data = { characters: {}, live: { danmaku: [], gifts: [], status:'离线' }, user: { bounties: [] } }; let currentBlockName = ''; let currentBlock = {}; const lines = text.split('\n'); for (const line of lines) { const blockMatch = line.match(/^\s*\[([^\]]+)\]\s*$/); if (blockMatch) { if (currentBlockName) { if(currentBlockName === '全局') data.global = currentBlock; else if(currentBlockName === '直播间') data.live = {...data.live, ...currentBlock}; else if(currentBlockName === '{{user}}') data.user = {...data.user, ...currentBlock}; else data.characters[currentBlockName] = currentBlock; } currentBlockName = blockMatch[1].trim(); currentBlock = {}; } else { const parts = line.split(':'); if(parts.length < 2) continue; const key = parts[0].trim(); const value = parts.slice(1).join(':').trim(); if (currentBlockName === '直播间') { if (key.startsWith('弹幕')) data.live.danmaku.push(value); else if (key.startsWith('礼物')) data.live.gifts.push(value); else currentBlock[key] = value; } else if (currentBlockName === '{{user}}' && key.startsWith('悬赏任务')) data.user.bounties.push(value); else currentBlock[key] = value; } } if(currentBlockName === '直播间') data.live = {...data.live, ...currentBlock}; return data; }
  function renderStatus(data) { const globalInfoEl = document.querySelector('.kld-global-info'); const tabsEl = document.querySelector('.kld-tabs'); if (!globalInfoEl || !tabsEl || !data.global) return; globalInfoEl.innerHTML = `<span><svg viewBox="0 0 24 24"><path d="M11.99 2C6.47 2 2 6.48 2 12s4.47 10 9.99 10C17.52 22 22 17.52 22 12S17.52 2 11.99 2zM12 20c-4.42 0-8-3.58-8-8s3.58-8 8-8 8 3.58 8 8-3.58 8-8 8z"></path><path d="M12.5 7H11v6l5.25 3.15.75-1.23-4.5-2.67z"></path></svg>${data.global['时间']||''}</span><span><svg viewBox="0 0 24 24"><path d="M20 3h-1V1h-2v2H7V1H5v2H4c-1.1 0-2 .9-2 2v16c0 1.1.9 2 2 2h16c1.1 0 2-.9 2-2V5c0-1.1-.9-2-2-2zm0 18H4V8h16v13z"></path></svg>${data.global['日期']||''}</span><span><svg viewBox="0 0 24 24"><path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7zm0 9.5c-1.38 0-2.5-1.12-2.5-2.5s1.12-2.5 2.5-2.5 2.5 1.12 2.5 2.5-1.12 2.5-2.5 2.5z"></path></svg>${data.global['地点']||''}</span>`; tabsEl.innerHTML = ''; const tabOrder = ['{{user}}', ...Object.keys(data.characters), '直播间']; tabOrder.forEach(name => { const isLiveTab = name === '直播间'; const isUser = name === '{{user}}'; if ((isLiveTab && !data.live) || (isUser && !data.user) || (!isLiveTab && !isUser && !data.characters[name])) return; const tab = document.createElement('div'); tab.className = 'kld-tab'; tab.dataset.char = name; tab.textContent = isUser ? '主播' : name; tab.addEventListener('click', () => { document.querySelectorAll('.kld-tab').forEach(t=>t.classList.remove('active')); document.querySelectorAll('.kld-live-view, .kld-char-view, .kld-user-view').forEach(v=>v.style.display='none'); tab.classList.add('active'); if(isLiveTab) renderLive(data.live); else if(isUser) renderUser(data.user); else renderCharacter(name, data.characters[name]); }); tabsEl.appendChild(tab); }); const firstTab = tabsEl.querySelector('.kld-tab'); if (firstTab) firstTab.click(); }
  function renderProgressBar(name, value, max=100) { const percentage = (parseInt(value) / max * 100) || 0; return `<div class="kld-gauge-item"><div class="gauge-name">${name}</div><div class="kld-progress-bar"><div class="kld-progress-fill" style="width: ${percentage}%;"></div><div class="kld-progress-text">${value||'0'}/${max}</div></div></div>`; }
  function renderParts(charData) { const parts = ['乳头', '小穴', '菊穴', '玉足', '肉棒']; let html = ''; parts.forEach(part => { if(charData[part]) { html += `<div class="kld-part-item"><span class="kld-part-name">${part}</span><span class="kld-part-status">${charData[part]}</span></div>`; } }); return html ? `<div class="kld-info-block kld-parts-block"><p><strong>身体部位:</strong></p><div class="kld-parts-grid">${html}</div></div>` : ''; }
  function renderCharacter(charName, charData) { const view = document.querySelector('.kld-char-view'); view.style.display = 'block'; let gaugesHtml = renderProgressBar('好感', charData['好感']) + renderProgressBar('欲望', charData['欲望']) + renderProgressBar('支配度', charData['支配度']); view.innerHTML = `<div class="kld-content-grid"><div class="kld-left-panel"><div class="kld-avatar-frame"><img class="kld-avatar" src="${avatarDatabase[charName] || ''}" alt="${charName}"></div><h3 class="kld-nickname">${charData['昵称']||''}</h3></div><div class="kld-right-panel"><div class="kld-gauge-grid">${gaugesHtml}</div><div class="kld-info-grid"><div class="kld-info-block"><p><strong>状态:</strong> <span>${charData['状态']||'无'}</span></p></div><div class="kld-info-block"><p><strong>衣着:</strong> <span>${charData['衣着']||'无'}</span></p></div><div class="kld-info-block kld-info-cmd"><p><strong>催眠指令:</strong> <span>${charData['催眠指令']||'无'}</span></p></div><div class="kld-info-block" style="grid-column: 1 / -1;"><p><strong>内心想法:</strong> <span>${charData['内心想法']||'无'}</span></p></div>${renderParts(charData)}</div></div></div>`; }
  function renderUser(userData) { const view = document.querySelector('.kld-user-view'); view.style.display = 'block'; let bountiesHtml = (userData.bounties || []).map(bounty => { const bountyMatch = bounty.match(/(.+)\(奖励:(.+)\)/); if (!bountyMatch) return `<div class="kld-bounty-block"><div class="kld-bounty-title">${bounty}</div></div>`; return `<div class="kld-bounty-block"><div class="kld-bounty-title">${bountyMatch[1]}</div><div class="kld-bounty-reward">奖励: ${bountyMatch[2]}</div></div>`; }).join(''); view.innerHTML = `<div class="kld-content-grid"><div class="kld-left-panel"><div class="kld-avatar-frame"><div class="user_avatar"></div></div></div><div class="kld-right-panel"><div class="kld-info-grid"><div class="kld-info-block"><p><strong>直播收益:</strong> <span style="color:var(--kld-text-gold);font-weight:bold;">${userData['直播收益']||'¥ 0'}</span></p></div><div class="kld-info-block"><p><strong>直播热度:</strong> <span style="color:var(--kld-text-live);font-weight:bold;">${userData['直播热度']||'0'}</span></p></div></div><div style="margin-top:10px;"><div class="kld-section-title">悬赏任务</div>${bountiesHtml || '<div class="kld-bounty-block" style="color:var(--kld-text-dark);">暂无悬赏</div>'}</div></div></div>`; }
  function renderLive(liveData) { const view = document.querySelector('.kld-live-view'); view.style.display = 'block'; const isLive = liveData['状态'] === '直播中'; let contentTitle = isLive ? '弹幕' : '评论'; let contentHtml = (isLive ? liveData.danmaku : liveData.danmaku)?.map(d => `<div class="kld-danmaku-item">${d}</div>`).join(''); let giftsHtml = isLive ? (liveData.gifts || []).map(gift => { const giftMatch = gift.match(/(.+)\sx\d+\s+\(.+\)\s+-\s+by\s+'(.+)'/); if (!giftMatch) return `<div class="kld-gift-item">${gift}</div>`; return `<div class="kld-gift-item"><span class="kld-gift-item-content">${gift.split(' - by')[0]}</span><span class="kld-gift-item-user">${giftMatch[2]}</span></div>`; }).join('') : ''; view.innerHTML = `<div class="kld-live-header"><div class="kld-live-title-container"><div class="kld-live-status-dot ${isLive ? 'live' : ''}"></div><div class="kld-live-title">${liveData['标题'] || '离线'}</div></div><div class="kld-live-viewers"><svg viewBox="0 0 24 24"><path d="M12 4.5C7 4.5 2.73 7.61 1 12c1.73 4.39 6 7.5 11 7.5s9.27-3.11 11-7.5c-1.73-4.39-6-7.5-11-7.5zM12 17c-2.76 0-5-2.24-5-5s2.24-5 5-5 5 2.24 5 5-2.24 5-5 5zm0-8c-1.66 0-3 1.34-3 3s1.34 3 3 3 3-1.34 3-3-1.34-3-3-3z"></path></svg><span>${isLive ? (liveData['观众']||'0') : 'N/A'}</span></div></div>${contentHtml ? `<div class="kld-section-title">${contentTitle}</div><div class="kld-danmaku-container">${contentHtml}</div>`: ''}${giftsHtml ? `<div class="kld-section-title">礼物</div><div class="kld-gift-container">${giftsHtml}</div>` : ''}`; }
  const toggleBtn = document.querySelector('.kld-toggle-btn'); const contentEl = document.querySelector('.kld-content'); toggleBtn.addEventListener('click', () => { if(contentEl.style.display === 'none'){contentEl.style.display = 'block'; toggleBtn.textContent = '折叠';}else{contentEl.style.display = 'none'; toggleBtn.textContent = '展开';}}); const rawData = dataContainer.textContent.trim(); if(rawData){const parsedData = parseData(rawData); renderStatus(parsedData); }
});
</script>
</body>
</html>
